/**
 * Semantic Code Classification for /admin/ide (owner, 2026-08-05).
 *
 * Classifies a real workspace file into a CodeCategory (what it does) and a
 * RiskLevel (how carefully it must be touched) — from REAL evidence only:
 *
 *   1. registry/module-registry.json — real layer/purpose/purpose_th text
 *      already generated by scripts/sync-registry.ts from actual exports.
 *   2. Real path structure — directory names that actually exist in this
 *      repo (verified against the real tree before writing any rule below,
 *      never guessed), e.g. cognitive/, services/ai/, gateway/, supabase/.
 *   3. registry/CONSTITUTION.json — real governance text. LOCKED files are
 *      never a hardcoded filename list here; they're DISCOVERED by
 *      scanning every rule string for the word "immutable" and extracting
 *      real path-like tokens from THAT rule's own text (see
 *      loadLockedPathsFromConstitution below) — Rule 107's declaration
 *      that generated evidence/ledger files are immutable is what produces
 *      registry/VALIDATION_RESULTS.json, registry/CHANGELOG.json,
 *      DNA_OS_HEALTH.json, etc. as LOCKED, not a manually maintained list.
 *      CRITICAL for core/shared/types.ts, registry/*.json, and migrations
 *      comes from Rule 116's real text naming exactly those resource
 *      types as requiring the Lock Manager + Validation Pipeline.
 *
 * A file with no registry entry AND no rule match is UNKNOWN — never
 * guessed into a category or risk level it has no real evidence for.
 *
 * classifyPath() is a pure function (registry + locked-set passed in) so
 * scripts/ide-regression-test.ts can exercise the real classification
 * rules against synthetic fixture data without touching this repo's own
 * files. classifyFile() is the real, I/O-backed entry point routes use.
 */
import { readFileSync } from "fs";
import path from "path";
import { WORKSPACE_ROOT } from "./fsSecurity";

export type CodeCategory =
  | "CORE_LOGIC" | "AI" | "INTEGRATION" | "WORKFLOW" | "DATABASE"
  | "SECURITY" | "UI" | "CONFIGURATION" | "DOCUMENTATION" | "UNKNOWN";

export type RiskLevel = "NORMAL" | "SENSITIVE" | "CRITICAL" | "LOCKED" | "UNKNOWN";

export interface ClassificationResult {
  category: CodeCategory;
  /** A finer-grained real capability WITHIN the category — e.g. AI/"Bridge
   * Claude", DATABASE/"Migration", CORE_LOGIC/"Tax". Mechanically derived
   * from the real path segment that follows the category's own root
   * directory (see detectCapability) — never a curated list of "known
   * capabilities"; a category with no such structure (CONFIGURATION,
   * DOCUMENTATION, UNKNOWN, or any path that doesn't fall under one of the
   * recognized capability-bearing roots) is null, never guessed. */
  capability: string | null;
  riskLevel: RiskLevel;
  /** Human-readable reasons, always traceable to a real source (registry
   * field, path pattern, or Constitution rule) — never invented. */
  evidence: string[];
  /** commandIds (from executionRegistry.ts) that a CRITICAL file's save
   * must trigger — empty unless riskLevel is CRITICAL. */
  requiredChecks: string[];
  /** Whether this path has a real entry in module-registry.json at all. */
  registered: boolean;
  /** Real purpose text from the registry, if registered — used for the
   * editor tooltip. Never fabricated when absent. */
  purposeTh: string | null;
}

interface ModuleRegistryEntry { owner: string; layer: string; purpose: string; purpose_th: string; exports: string[]; status?: string }
export interface ModuleRegistry { modules: Record<string, ModuleRegistryEntry> }

let cachedRegistry: ModuleRegistry | null = null;
let cachedLockedPaths: Set<string> | null = null;

export function loadModuleRegistry(): ModuleRegistry {
  if (cachedRegistry) return cachedRegistry;
  const raw = readFileSync(path.join(WORKSPACE_ROOT, "registry/module-registry.json"), "utf-8");
  cachedRegistry = JSON.parse(raw);
  return cachedRegistry!;
}

function collectStrings(node: unknown, out: string[]) {
  if (typeof node === "string") { out.push(node); return; }
  if (Array.isArray(node)) { for (const v of node) collectStrings(v, out); return; }
  if (node && typeof node === "object") { for (const v of Object.values(node)) collectStrings(v, out); }
}

const PATH_TOKEN_RE = /(?:registry\/|core\/shared\/)?[A-Za-z0-9_-]+\.(?:json|ts|tsx)/g;

/** Real discovery, not a hardcoded list — see module doc comment above. */
export function loadLockedPathsFromConstitution(): Set<string> {
  if (cachedLockedPaths) return cachedLockedPaths;
  const set = new Set<string>();
  try {
    const raw = readFileSync(path.join(WORKSPACE_ROOT, "registry/CONSTITUTION.json"), "utf-8");
    const parsed = JSON.parse(raw);
    const strings: string[] = [];
    collectStrings(parsed, strings);
    for (const s of strings) {
      if (/immutable/i.test(s)) {
        const matches = s.match(PATH_TOKEN_RE) ?? [];
        for (const m of matches) set.add(m);
      }
    }
  } catch {
    // No Constitution file / unreadable — no LOCKED evidence. Never guessed.
  }
  cachedLockedPaths = set;
  return set;
}

function detectCategory(relPath: string, entry: ModuleRegistryEntry | undefined): { category: CodeCategory; evidence: string[] } {
  const purposeText = `${entry?.purpose ?? ""} ${entry?.purpose_th ?? ""}`;

  if (/\.md$/i.test(relPath) || /(^|\/)docs\//.test(relPath) || /(^|\/)readme/i.test(relPath)) {
    return { category: "DOCUMENTATION", evidence: ["path matches documentation pattern (docs/, *.md, README*)"] };
  }
  if (/(^|\/)core\/auth\//.test(relPath) || /(^|\/)auth\//i.test(relPath) || /requireauth/i.test(relPath) || /\/session\.ts$/.test(relPath) || /permission/i.test(relPath) || /middleware/i.test(relPath)) {
    return { category: "SECURITY", evidence: ["path matches auth/session/permission/middleware pattern"] };
  }
  if (/workflow/i.test(relPath) || /(^|\/)jobs\//.test(relPath)) {
    return { category: "WORKFLOW", evidence: ["path matches workflow/jobs pattern"] };
  }
  if (/(^|\/)cognitive\//.test(relPath) || /(^|\/)services\/ai\//.test(relPath) || /(^|\/)services\/ai-connection\//.test(relPath) || /(^|\/)presenter\//.test(relPath) || /\bAI\b/.test(purposeText)) {
    return { category: "AI", evidence: ["path matches cognitive/AI-service/presenter pattern, or registry purpose mentions AI"] };
  }
  if (/(^|\/)gateway\//.test(relPath) || /integration-gateway/.test(relPath) || /(^|\/)plugins\//.test(relPath) || /connector/i.test(relPath)) {
    return { category: "INTEGRATION", evidence: ["path matches gateway/connector/plugins pattern"] };
  }
  if (/(^|\/)supabase\//.test(relPath) || /(^|\/)services\/supabase\//.test(relPath) || /\/migrations\//.test(relPath) || /database/i.test(relPath)) {
    return { category: "DATABASE", evidence: ["path matches supabase/migrations/database pattern"] };
  }
  if (/^components\//.test(relPath) || /^styles\//.test(relPath) || (/^app\//.test(relPath) && !/\/api\//.test(relPath) && /\.tsx$/.test(relPath))) {
    return { category: "UI", evidence: ["path matches components/ or a non-API app page/component"] };
  }
  if (/^registry\/.*\.json$/.test(relPath) || /\.config\.(ts|js|mjs|cjs)$/.test(relPath) || /^(package\.json|tsconfig.*\.json|next\.config\.\w+|tailwind\.config\.\w+|postcss\.config\.\w+|\.env.*|\.gitignore)$/.test(path.basename(relPath)) || entry?.layer === "scripts") {
    return { category: "CONFIGURATION", evidence: ["path/layer matches configuration or build-tooling pattern"] };
  }
  if (/^(engines|core|app\/api|gateway)\//.test(relPath)) {
    return { category: "CORE_LOGIC", evidence: ["path is under a real backend/business-logic layer (engines/, core/, app/api/)"] };
  }
  return { category: "UNKNOWN", evidence: [] };
}

/** Real path segments this repo actually has directly under each root —
 * checked against the live tree before writing this table, same discipline
 * as detectCategory's roots. The capability is that segment itself
 * (title-cased for display), NOT a curated enum like "Vision"/"OCR" that
 * this codebase has no evidence for — inventing those would violate the
 * evidence-based principle just as much as guessing a category would. */
const CAPABILITY_ROOTS: string[] = [
  "cognitive/", "services/ai-connection/", "services/ai/", "services/supabase/",
  "supabase/migrations/", "engines/", "core/auth/", "gateway/", "plugins/", "components/",
];

function titleCaseSegment(segment: string): string {
  const base = segment.replace(/\.(ts|tsx|js|jsx|json|md|sql)$/i, "");
  const spaced = base.replace(/[-_]/g, " ").replace(/([a-z0-9])([A-Z])/g, "$1 $2");
  return spaced.split(" ").filter(Boolean).map((w) => w[0].toUpperCase() + w.slice(1)).join(" ");
}

function detectCapability(relPath: string): { capability: string | null; evidence: string[] } {
  // Every migration file is real evidence of the same capability — the
  // directory itself, not the individual filename (a timestamped filename
  // carries no meaningful capability signal).
  if (/^supabase\/migrations\//.test(relPath)) {
    return { capability: "Migration", evidence: ["every file under supabase/migrations/ is a real schema migration"] };
  }
  for (const root of CAPABILITY_ROOTS) {
    const re = new RegExp(`^${root.replace(/\//g, "\\/")}`);
    if (re.test(relPath)) {
      const rest = relPath.slice(root.length);
      const firstSegment = rest.split("/")[0];
      if (!firstSegment) continue;
      return { capability: titleCaseSegment(firstSegment), evidence: [`derived from the real path segment directly under ${root}`] };
    }
  }
  return { capability: null, evidence: [] };
}

function detectRisk(relPath: string, category: CodeCategory, lockedPaths: Set<string>, registered: boolean): { riskLevel: RiskLevel; evidence: string[]; requiredChecks: string[] } {
  if (lockedPaths.has(relPath) || lockedPaths.has(path.basename(relPath))) {
    return {
      riskLevel: "LOCKED",
      evidence: ["registry/CONSTITUTION.json declares this a generated/ledger file that is immutable once written (Rule 107 class)"],
      requiredChecks: [],
    };
  }
  if (relPath === "core/shared/types.ts") {
    return {
      riskLevel: "CRITICAL",
      evidence: ["registry/CONSTITUTION.json Rule 116 names core/shared/types.ts as a governed resource requiring the Lock Manager + Validation Pipeline before edit"],
      requiredChecks: ["typecheck"],
    };
  }
  if (/^registry\/.*\.json$/.test(relPath)) {
    return {
      riskLevel: "CRITICAL",
      evidence: ["registry/CONSTITUTION.json Rule 116 names registry/*.json as a governed resource requiring the Lock Manager + Validation Pipeline before edit"],
      requiredChecks: ["typecheck"],
    };
  }
  if (/\/migrations\//.test(relPath)) {
    return {
      riskLevel: "CRITICAL",
      evidence: ["registry/CONSTITUTION.json Rule 116 names migrations as a governed resource requiring the Lock Manager + Validation Pipeline before edit"],
      requiredChecks: ["typecheck"],
    };
  }
  if (category === "SECURITY" && (/(^|\/)core\/auth\//.test(relPath) || /requireauth/i.test(relPath) || /\/session\.ts$/.test(relPath))) {
    return {
      riskLevel: "CRITICAL",
      evidence: ["real production auth/session gatekeeper — every /api/admin/* route depends on this"],
      requiredChecks: ["typecheck"],
    };
  }
  if (!registered) {
    return { riskLevel: "UNKNOWN", evidence: [], requiredChecks: [] };
  }
  if (category === "SECURITY" || category === "DATABASE" || category === "INTEGRATION") {
    return { riskLevel: "SENSITIVE", evidence: [`category ${category} is a real external/production trust boundary`], requiredChecks: [] };
  }
  if (/^app\/api\//.test(relPath)) {
    return { riskLevel: "SENSITIVE", evidence: ["real backend API route surface"], requiredChecks: [] };
  }
  return { riskLevel: "NORMAL", evidence: [], requiredChecks: [] };
}

export function classifyPath(relPath: string, registry: ModuleRegistry, lockedPaths: Set<string>): ClassificationResult {
  const entry = registry.modules[relPath];
  const registered = !!entry;
  const { category, evidence: categoryEvidence } = detectCategory(relPath, entry);
  const { capability, evidence: capabilityEvidence } = detectCapability(relPath);
  const { riskLevel, evidence: riskEvidence, requiredChecks } = detectRisk(relPath, category, lockedPaths, registered);
  const evidence = [...categoryEvidence, ...capabilityEvidence, ...riskEvidence];
  if (!registered && category === "UNKNOWN") {
    evidence.push("not present in registry/module-registry.json — no real evidence available");
  }
  return { category, capability, riskLevel, evidence, requiredChecks, registered, purposeTh: entry?.purpose_th ?? null };
}

/** Real, I/O-backed entry point — routes call this. */
export function classifyFile(relPath: string): ClassificationResult {
  return classifyPath(relPath, loadModuleRegistry(), loadLockedPathsFromConstitution());
}

export const CATEGORY_LABELS: Record<CodeCategory, string> = {
  CORE_LOGIC: "Core Logic", AI: "AI", INTEGRATION: "Integration", WORKFLOW: "Workflow",
  DATABASE: "Database", SECURITY: "Security", UI: "UI", CONFIGURATION: "Configuration",
  DOCUMENTATION: "Documentation", UNKNOWN: "Unknown",
};
